const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '向上拔瓶塞时，木塞受力示意' },
      { kind: 'text', payload: '拉力 F' },
      { kind: 'text', payload: '瓶内气压与摩擦的合力' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var cx = W * 0.58;
    var bottleHalf = W * 0.08;
    var corkHalf = W * 0.066;
    var mouthHalf = W * 0.105;
    var yMouth = H * 0.52;
    var yNeckBottom = H * 0.82;
    var yBodyBottom = H * 0.96;
    var yCorkTop = H * 0.40;
    var yCorkBottom = H * 0.58;
    var yArrowFTop = H * 0.20;
    var yArrowDBottom = H * 0.76;
    var lineW = Math.max(2, H * 0.008);
    var headLen = Math.max(10, H * 0.035);
    var headHalf = Math.max(5, H * 0.016);
    var shaftHalf = Math.max(2, H * 0.006);

    function rectCommands(x1, y1, x2, y2) {
      return [
        ['M', x1, y1],
        ['L', x2, y1],
        ['L', x2, y2],
        ['L', x1, y2],
        ['Z']
      ];
    }

    function lineRectCommands(x1, y1, x2, y2, w) {
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      if (len === 0) {
        return rectCommands(x1 - w / 2, y1 - w / 2, x1 + w / 2, y1 + w / 2);
      }
      var ux = dx / len;
      var uy = dy / len;
      var px = -uy * w / 2;
      var py = ux * w / 2;
      return [
        ['M', x1 + px, y1 + py],
        ['L', x2 + px, y2 + py],
        ['L', x2 - px, y2 - py],
        ['L', x1 - px, y1 - py],
        ['Z']
      ];
    }

    function arrowShapeCommands(x1, y1, x2, y2) {
      var dx = x2 - x1;
      var dy = y2 - y1;
      var len = Math.sqrt(dx * dx + dy * dy);
      var ux = dx / len;
      var uy = dy / len;
      var px = -uy;
      var py = ux;
      var bx = x2 - ux * headLen;
      var by = y2 - uy * headLen;
      var shaft = [
        ['M', x1 + px * shaftHalf, y1 + py * shaftHalf],
        ['L', bx + px * shaftHalf, by + py * shaftHalf],
        ['L', bx - px * shaftHalf, by - py * shaftHalf],
        ['L', x1 - px * shaftHalf, y1 - py * shaftHalf],
        ['Z']
      ];
      var head = [
        ['M', x2, y2],
        ['L', bx + px * headHalf, by + py * headHalf],
        ['L', bx - px * headHalf, by - py * headHalf],
        ['Z']
      ];
      return shaft.concat(head);
    }

    var bottleCommands = [];
    function addBottleLine(x1, y1, x2, y2, w) {
      var cmds = lineRectCommands(x1, y1, x2, y2, w);
      for (var i = 0; i < cmds.length; i++) {
        bottleCommands.push(cmds[i]);
      }
    }

    addBottleLine(cx - mouthHalf, yMouth, cx + mouthHalf, yMouth, lineW * 1.3);
    addBottleLine(cx - bottleHalf, yMouth, cx - bottleHalf, yNeckBottom, lineW);
    addBottleLine(cx + bottleHalf, yMouth, cx + bottleHalf, yNeckBottom, lineW);
    addBottleLine(cx - bottleHalf, yNeckBottom, cx - bottleHalf * 1.4, H * 0.88, lineW);
    addBottleLine(cx - bottleHalf * 1.4, H * 0.88, cx - bottleHalf * 2, yBodyBottom, lineW);
    addBottleLine(cx + bottleHalf, yNeckBottom, cx + bottleHalf * 1.4, H * 0.88, lineW);
    addBottleLine(cx + bottleHalf * 1.4, H * 0.88, cx + bottleHalf * 2, yBodyBottom, lineW);
    addBottleLine(cx - bottleHalf * 2, yBodyBottom, cx + bottleHalf * 2, yBodyBottom, lineW);

    var corkBorder = rectCommands(cx - corkHalf - 2, yCorkTop - 2, cx + corkHalf + 2, yCorkBottom + 2);
    var corkFill = rectCommands(cx - corkHalf, yCorkTop, cx + corkHalf, yCorkBottom);
    var arrowF = arrowShapeCommands(cx, yCorkTop, cx, yArrowFTop);
    var arrowDown = arrowShapeCommands(cx, yCorkBottom, cx, yArrowDBottom);

    return {
      schemaVersion: 1,
      sceneId: 'cork-force-diagram',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'bottleLines', commands: bottleCommands },
        { id: 'corkBorder', commands: corkBorder },
        { id: 'corkFill', commands: corkFill },
        { id: 'arrowF', commands: arrowF },
        { id: 'arrowDown', commands: arrowDown }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'bottleLines', fill: '#26354a' },
          { type: 'path', pathId: 'corkBorder', fill: '#6B4A2B' },
          { type: 'path', pathId: 'corkFill', fill: '#C89B6D' },
          { type: 'path', pathId: 'arrowF', fill: '#C0392B' },
          { type: 'path', pathId: 'arrowDown', fill: '#1F5FA8' },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: W / 2, y: H * 0.08 }, hAlign: 'center', vAlign: 'middle', color: '#26354a' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: cx - 20, y: (yCorkTop + yArrowFTop) / 2 }, hAlign: 'right', vAlign: 'middle', color: '#C0392B' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: cx - bottleHalf - 20, y: (yCorkBottom + yArrowDBottom) / 2 }, hAlign: 'right', vAlign: 'middle', color: '#1F5FA8' }
        ]
      }
    };
  }
};
